insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F0',0,'PRE','Primeira conversa','Fazer o cliente entender o próprio problema melhor do que entendia antes.',null,false,null,1,'Aula 18') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F0',0,'Agendar a call com o decisor','Só com quem decide e assina. Se for com um intermediário, a conversa não fecha nada.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F0',1,'Rodar as 7 perguntas da call, na ordem','Sete perguntas em ordem fixa. Elas fazem o cliente entender o problema dele melhor do que entendia antes de falar com você.','fase') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F0',2,'Devolver reformulação e confirmar a cada rodada','Depois de cada resposta, devolva com suas palavras: “então o que você está dizendo é…”. Ele confirma ou corrige — e a cada correção você acerta mais.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F0',3,'Na pergunta 06, subir a escada de ancoragem até chegar no valor','Perguntas de valor em escada: quanto vale resolver isso, quanto custa não resolver, quanto já gastou tentando. Você chega no número sem falar de preço.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F0',4,'Anotar literal a resposta da pergunta 07','Copie a frase dele, palavra por palavra. Ela vira a abertura da sua proposta e o argumento que fecha a venda.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F0',5,'Registrar ponto A, ponto B, prioridade e faixa de investimento','Ponto A é onde a marca está. Ponto B é onde ele quer chegar. A distância entre os dois é o escopo do projeto.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F0',6,'Classificar o nível de consciência do cliente e anotar os sinais de alerta','Consciência: ele sabe que tem problema? sabe qual é? sabe que existe solução? Sinais de alerta: quer logo em uma semana, não tem verba, sócio ausente, já rodou com três agências.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F1',1,'PRE','Contrato e preparação','Converter confiança em contrato e deixar o processo visível.','Contrato assinado',false,null,7,'M03 A13') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',0,'Enviar sua apresentação institucional','Quem é você, como trabalha, o que já entregou. Manda antes da proposta, não junto — proposta com portfólio dentro vira orçamento.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',1,'Enviar acordo de confidencialidade (NDA) se o cliente estiver segurando informação','NDA = acordo de confidencialidade. Se o cliente trava faturamento, margem, planos ou briga entre sócios, o NDA destrava. Sem número, o diagnóstico sai raso.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',2,'Montar a proposta técnica: escopo, etapas, entregáveis e condições','O que será feito, em quantas etapas, o que ele recebe em cada uma e o que você precisa dele. É esse documento que evita retrabalho depois.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',3,'Montar a proposta comercial (7 a 8 slides)','Curta. Problema, caminho, entregas, investimento, prazo, condições, próximo passo. Uma ideia por slide.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',4,'Assinar o contrato e confirmar a entrada do pagamento','Projeto só começa com contrato assinado E entrada paga. Sem isso a agenda não é bloqueada.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',5,'Definir com o cliente quem participa das entrevistas e do workshop','Nome e cargo de cada um. Quem decide, quem fala com o cliente todo dia, quem cuida da comunicação. Máximo de 6 a 8 no workshop.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',6,'Perguntar em que formato o cliente quer receber os relatórios','PDF, apresentação, Notion, site? Perguntar agora evita refazer a entrega inteira depois.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',7,'Criar pasta do projeto no Drive','Uma pasta por cliente, com subpastas por etapa. Tudo que for gerado vive lá — é o que você entrega no fim.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',8,'Agendar entrevistas e imersão no Calendar','Bloqueie a data do workshop primeiro, é a mais difícil de juntar todo mundo. As entrevistas se encaixam antes.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F1',9,'Pedir aos fundadores a história de criação, por escrito, antes do workshop','Como a empresa nasceu, quem teve a ideia, o que aconteceu no começo. Vem pronto de casa e economiza uma hora de sala.','ex:E1') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F2',2,'COLETANDO','Entrevistas individuais','Chegar ao workshop sendo quem mais sabe do que acontece lá dentro.',null,false,null,5,'M05 A03') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',0,'Listar os entrevistados (decisores + quem fala com o cliente + comunicação)','Sócios e diretores, quem atende cliente todo dia, e quem escreve pela marca. Quem atende sabe coisas que o dono não sabe.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',1,'Agendar uma call individual por pessoa, fora do ambiente da empresa','Individual e fora da empresa — presencial num café ou por call. Junto do chefe ninguém fala a verdade.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',2,'Declarar confidencialidade na abertura de cada entrevista','Diga na cara: nada do que for dito aqui vai com nome para o relatório. Sem isso a entrevista rende metade.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',3,'Rodar o roteiro nos quatro blocos, anotando à mão','Negócio, Audiência, Valor e Estória. Anotar à mão mantém o olho na pessoa e já filtra o que importa.','fase') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',4,'Gravar e transcrever cada entrevista','Grave sempre (com autorização). A transcrição vira matéria-prima do diagnóstico e do naming.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',5,'Mapear tensões, divergências e quem domina a conversa','Onde as respostas se contradizem, o que só uma pessoa diz, quem todo mundo cita. Isso define como você conduz o workshop.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',6,'Escolher os exercícios do workshop e anotar por quê','Nem todo exercício serve para todo cliente. Escolha a partir do que apareceu nas entrevistas e anote o motivo — é o que sustenta sua condução.','passo:F3') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F2',7,'Montar o plano de workshop com exemplos e histórias por bloco','Ordem dos blocos, tempo de cada um, e um exemplo ou história para abrir cada exercício. Workshop sem roteiro vira reunião.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F3',3,'COLETANDO','Workshop com o cliente','Extrair a informação que as pessoas não sabem que têm, nos quatro eixos.','Material bruto + decisões ao vivo',false,null,2,'M05 A02–A11') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',0,'Abrir escrevendo o objetivo e reafirmando o espaço seguro','Escreva o objetivo do dia num lugar visível e diga em voz alta: aqui não tem resposta errada e nada sai com nome. É isso que solta a sala.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',1,'Configurar a gravação separada por bloco','Um arquivo por bloco, não um de seis horas. Depois você acha o trecho em minutos, não em horas.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',2,'Negócio — rodar os exercícios escolhidos','Quem é o negócio, de onde veio, o que vende, para onde vai.','eixo:N') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',3,'Audiência — rodar os exercícios escolhidos','Para quem a marca fala, o que essa pessoa quer e o que ela sente.','eixo:A') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',4,'Valor — rodar os exercícios escolhidos','O que a marca promete, contra quem compete e por que alguém escolheria ela.','eixo:V') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',5,'Estória — rodar os exercícios escolhidos','De onde a marca veio, no que acredita e como se comporta.','eixo:E') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',6,'Marcar decisões ao vivo e deixar os rascunhos visíveis','Quando a sala fechar uma decisão, escreva no quadro e leia em voz alta. Rascunho apagado é decisão perdida.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',7,'Fechar com o objetivo principal em um parágrafo','No fim do dia, todo mundo junto escreve um parágrafo: qual é o objetivo principal desta marca. É o fecho e o teste do dia.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F3',8,'Cumprir a agenda no minuto','Comece e termine na hora marcada. Estourar o horário derruba a energia da sala e queima o último bloco.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F4',4,'EXPLORANDO','Organização do material','Transformar a montanha de informação em material organizado em NAVE.',null,false,null,2,'M06 A02') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F4',0,'No dia seguinte: gravar 30–60 min de percepções para quem não participou','No dia seguinte, sozinho, grave falando o que você viu — como se explicasse para um sócio que não estava lá. Sai insight que não sai escrevendo.','fase') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F4',1,'Transcrever imersão e descompressão','Workshop e descompressão viram texto. É esse texto que a IA lê e que você cita no relatório.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F4',2,'Rodar a IA em cada bloco: Negócio, Audiência, Valor, Estória','Peça para organizar o material bruto em quatro blocos separados. Um por vez, nunca tudo de uma vez.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F4',3,'Pedir à IA: contradições, incoerências, repetições e hipóteses adicionais','Peça o que você não vai ver: onde o cliente se contradiz, o que ele repete demais, o que ficou faltando.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F4',4,'Revisar o que a IA devolveu e aceitar ou descartar item a item','A IA organiza, você decide. Item por item: aceita, corta ou reescreve. Nada entra no relatório sem passar por você.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F4',5,'Montar a primeira versão do relatório no formato que o cliente escolheu','Ainda é rascunho, mas já no formato final que o cliente pediu. Escrever direto no formato evita retrabalho.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F5',5,'EXPLORANDO','Pesquisa e validação','Tirar o viés do cliente. Não vendemos achômetro.',null,false,null,4,'M06 A03') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F5',0,'Listar as hipóteses a validar (toda afirmação forte do cliente)','Toda frase forte que o cliente disse (“somos os únicos que…”, “nosso público é…”) vira uma hipótese a checar.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F5',1,'Concorrência: visitar os pontos de contato de todos os players','Site, Instagram, loja, atendimento, embalagem. Como cliente, não como analista — compre, pergunte, reclame.','ex:DG2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F5',2,'Concorrência: mapear promessa real, palavras-chave e necessidades vagas','O que ele promete de verdade, quais palavras ele domina, e qual necessidade ninguém está atendendo. O espaço vago é o seu.','ex:DG2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F5',3,'Referências externas: levantar 2–3 análogos fora da categoria','Marcas de outro setor que resolvem um problema parecido. É de onde vem a ideia que a categoria inteira não teve.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F5',4,'Percepção externa digital: redes, fóruns, Reclame Aqui, reviews','Comentário, review, fórum, Reclame Aqui. O que as pessoas dizem quando a marca não está ouvindo.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F5',5,'Percepção externa: conversar com cliente atual, ex-cliente e quem voltou','Cliente atual, ex-cliente e quem foi embora e voltou. Os três contam histórias diferentes da mesma marca.','ex:DG3') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F5',6,'Marcar cada hipótese como confirmada, refutada ou não verificável','Confirmada, refutada ou não verificável. Hipótese refutada é o achado mais valioso do diagnóstico.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F6',6,'EXPLORANDO','Diagnóstico','Emitir o laudo. Não é cópia e cola dos post-its.','Relatório de Diagnóstico',true,'Cliente aprovou o diagnóstico',3,'M06 A01/A04') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F6',0,'Organizar o relatório em Negócio, Audiência, Valor e Estória','Mesma estrutura dos quatro blocos. O cliente reconhece a lógica e acompanha sem se perder.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F6',1,'Passar as 5 validações críticas, cada uma com a evidência que sustenta','Cada afirmação forte do relatório precisa de uma fonte: trecho de entrevista, dado de pesquisa ou print do concorrente.','ex:DG4') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F6',2,'Escrever o laudo: desafios, oportunidades e necessidades de mudança','Laudo é diagnóstico, não solução. Desafios, oportunidades e o que precisa mudar — sem propor a marca nova ainda.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F6',3,'Passar o checklist de fechamento do diagnóstico','Antes de apresentar: tem evidência para tudo? tem contradição não resolvida? tem promessa de solução escondida?',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F6',4,'Apresentar deixando claro que é laudo, não solução','Diga na abertura: hoje é o raio-x, não o remédio. Sem isso o cliente cobra logo na primeira reunião.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F6',5,'Perguntar o que não ficou claro, o que discorda, o que está errado','Pergunte as três explicitamente. O que ele discorda agora é barato; o que ele discorda depois custa o projeto.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F6',6,'Registrar a aprovação do cliente por escrito','Por e-mail ou no documento, com data. É este aceite que destrava os próximos passos aqui no fluxo.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F7',7,'EXPLORANDO','Redação da estratégia','Decidir o que fazer com tudo aquilo que sabemos.',null,false,null,5,'M06 A05–A07') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',0,'Recuperar as anotações de insight feitas durante o diagnóstico','Ao longo do diagnóstico você anotou ideias soltas. É a hora de puxar todas — elas viram os blocos da estratégia.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',1,'Bloco 1 — Promessa / transformação','Que transformação a marca entrega. Não é o que ela faz, é o que muda na vida de quem compra.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',2,'Bloco 2 — Diretrizes de personalidade com do''s e don''ts','Como a marca se comporta. Cada atributo com o que ele autoriza e o que ele proíbe.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',3,'Bloco 3 — Diretrizes de valores com sinais vermelhos','No que a marca não abre mão. Com o sinal vermelho: o que fere aquele valor.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',4,'Bloco 4 — Oportunidades de mercado','Os espaços que a pesquisa mostrou vagos — e quais deles esta marca consegue ocupar.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',5,'Bloco 5 — Principais mensagens, cada uma com seu papel','O que a marca precisa comunicar, e para que serve cada mensagem: atrair, convencer, diferenciar, reter.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',6,'Bloco 6 — Declaração de posicionamento analítica','Uma frase de trabalho, interna, que diz para quem, o quê, contra quem e por quê. Não é slogan.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',7,'Escrever escolhas e renúncias','Toda escolha corta alguma coisa. Escrever o que a marca deixa de ser evita briga depois.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',8,'Sinalizar riscos e limitações (não fuja da notícia difícil)','Se tem risco no caminho escolhido, diga agora. Consultor que só dá boa notícia não é ouvido na hora difícil.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',9,'Passar o texto pelo filtro dos 7 erros clássicos','Genérico, óbvio, copiado do concorrente, tático demais, longo demais, sem evidência, sem renúncia.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F7',10,'Conferir que não desceu para tática e execução','Estratégia diz o que e por quê. Se apareceu “fazer post”, “rodar campanha”, subiu de camada — corte.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F8',8,'EXPLORANDO','Posicionamento e plataforma','Achar o espaço proprietário e validar a coerência do conjunto.','Declaração + Plataforma de Marca',false,null,2,'M06 A08/A09') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F8',0,'Rodar o teste do contrário','Inverta a declaração. Se o contrário for absurdo (“queremos clientes insatisfeitos”), sua frase não diz nada.','ex:ES2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F8',1,'Rodar o teste do concorrente','Cole o nome do concorrente no lugar do seu. Se continuar verdadeiro, não é posicionamento, é descrição de categoria.','fase') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F8',2,'Rodar o teste sem o segmento de mercado','Tire a palavra do segmento. Se a frase desmonta, você está apoiado na categoria, não numa ideia própria.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F8',3,'Reescrever se reprovou em qualquer um','Reprovou em um dos três? Reescreve. É normal reescrever quatro, cinco vezes.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F8',4,'Sintetizar a Plataforma de Marca nos 7 elementos','Propósito, visão, missão, valores, personalidade, promessa e posicionamento — em uma página só.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F8',5,'Checar genericidade campo a campo','Campo a campo: isso serviria para qualquer marca do setor? Se sim, está genérico. Refaça.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F9',9,'EXPLORANDO','Apresentação da estratégia','Validar o caminho escolhido entre caminhos possíveis.','Relatório de Estratégia',true,'Cliente aprovou a estratégia',2,'M06 A11') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F9',0,'Preparar a apresentação começando pelo diagnóstico','Retome o diagnóstico aprovado antes de mostrar a estratégia. Sem a régua, a proposta parece opinião.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F9',1,'Apresentar em tom de validação, nunca como sacada genial','Você não teve uma ideia genial: você seguiu o que o material mostrou. Esse tom faz o cliente assinar embaixo junto.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F9',2,'Mostrar a lógica de A até B com o trecho que sustenta','Para cada decisão, mostre de onde ela veio: a frase da entrevista, o dado, o print. É isso que blinda a estratégia.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F9',3,'Documentar feedbacks e dúvidas','Anote tudo na hora, inclusive o que parecer bobo. Objeção não anotada volta na entrega final.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F9',4,'Ajustar com base em dado, não em opinião','“Não gostei” não muda estratégia. “Isso contradiz o que fazemos com o cliente X” muda. Peça o dado antes de mexer.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F9',5,'Registrar a aprovação do cliente por escrito','Aceite formal, com data. É o que libera a fase de criação aqui no fluxo.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F9',6,'Alinhar cronograma da fase de identidade','Datas de naming, verbal e visual, e quando ele precisa estar disponível para aprovar.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F10',10,'CRIANDO','Naming','Criar um nome estratégico, memorável e juridicamente viável.','Nome escolhido + conceito',false,null,12,'M07 A01–A04') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',0,'Refazer o mapeamento com foco no nome','Reler tudo com uma pergunta só na cabeça: que palavras esta marca já usa e quais ela merece usar.','ex:NM1') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',1,'Validar com o cliente o caminho: descritivo, sugestivo ou metafórico','Descritivo diz o que faz, sugestivo insinua, metafórico cria universo. Alinhe antes de gerar nome, senão você joga fora 200 opções.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',2,'Caça-palavras nas transcrições','Passe pelas transcrições marcando toda palavra incomum, gíria interna, jeito de falar. Nome bom costuma já estar dito.','ex:NM2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',3,'Multiplicação de palavras (mapas mentais)','Cada palavra puxa cinco: sinônimo, oposto, som parecido, tradução, imagem. É o volume que gera o nome.','ex:NM2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',4,'Chuva de ideias com as 7 operações','Juntar, cortar, inverter, trocar letra, importar de outra língua, inventar sufixo, usar nome próprio.','ex:NM2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',5,'Registrar a origem de cada nome na planilha','De onde veio cada nome. Na apresentação, a origem vale mais que o nome — é ela que convence.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',6,'Passar os 7 filtros: estratégia, grafia, pronúncia, originalidade, durabilidade, memorabilidade e feedback honesto','Sete filtros em sequência. O nome que passa nos sete vai para os testes; o que cai fica na reserva.','ex:NM3') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',7,'Fazer os testes de memória: boteco, família e lista com recall','Fale o nome num bar barulhento, para um parente, e numa lista de dez — pergunte quais ele lembra no dia seguinte.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',8,'Checar domínio e @ nas redes','Domínio .com e .com.br, e o @ nas redes que a marca vai usar. Nome sem casa digital morre.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',9,'Jogar cada nome inventado no Google, inclusive imagens','Inclusive na aba de imagens. Nome inventado pode significar algo horrível em outro idioma.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',10,'Enviar finalistas ao escritório de marcas (INPI)','Busca de anterioridade no INPI antes de apresentar. Apresentar nome que não registra queima sua credibilidade.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',11,'Deixar de 20 a 40 nomes alinhados na reserva','Se o finalista cair no registro, você precisa do próximo já pronto — não de mais um mês de trabalho.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F10',12,'Apresentar SEM pedir aprovação na hora','Apresente, explique a origem e mande ele dormir com a ideia. Nome escolhido na emoção volta atrás na semana seguinte.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F11',11,'CRIANDO','Identidade verbal','Expressar a personalidade da marca através da linguagem.',null,false,null,10,'M07 A05–A11') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',0,'Definir as principais mensagens e o papel de cada uma','As mensagens que a marca precisa repetir sempre, e para que serve cada uma.','ex:VB1') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',1,'Escrever a narrativa da marca em quatro etapas (4–5 parágrafos, uso interno)','Conceito, problema do público, gancho e solução. Texto interno — é a matriz de onde sai todo o resto.','ex:VB1') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',2,'Listar os assets verbais (lemas, mantras, palavras sagradas, rituais)','Frases, palavras e rituais que só essa marca usa. É o que faz o texto soar dela mesmo.','fase') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',3,'Derivar a voz dos atributos que se expressam no campo verbal','Nem todo atributo vira voz. Pegue os que se expressam em palavra: “direto”, “provocador”, “acolhedor”.','ex:VB2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',4,'Nomear as vozes — máximo três','Três é o teto. Mais que isso ninguém do time consegue usar.','ex:VB2') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',5,'Definir 2 a 4 tons por voz com emoção, contexto e exemplo','Tom é a voz num contexto. Mesma marca, tom diferente no erro do sistema e no e-mail de boas-vindas.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',6,'Montar o dicionário: palavras que usamos e que evitamos','Duas colunas: palavras que usamos e palavras que evitamos. É o item mais usado do guia inteiro.','ex:VB3') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',7,'Testar cada palavra na boca do concorrente — se serve pra ele, não é sua','Se o concorrente pode dizer a mesma palavra sem estranheza, ela não é da sua marca.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',8,'Escrever o guia de estilo','Regras práticas: como escrever números, como tratar o leitor, tamanho de frase, uso de emoji.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',9,'Escrever o manifesto, se fizer sentido','Texto de bandeira, para o time e para quem chega. Só escreva se a marca tiver o que defender.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',10,'Criar a tagline, se fizer sentido','Frase curta que acompanha o logo. Não é obrigatória — marca sem tagline é melhor que tagline fraca.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F11',11,'Produzir um antes-e-depois para mostrar o impacto','Pegue textos reais da marca e reescreva na voz nova, lado a lado. É o que faz o cliente entender o que comprou.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F12',12,'CRIANDO','Discurso da marca','Tornar posicionamento e linguagem utilizáveis desde já.','Key Word',true,'Cliente aprovou o território verbal',3,'M07 A12') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F12',0,'Escrever a versão elevador (30s)','30 segundos. Alguém pergunta “o que vocês fazem?” num elevador. Precisa ficar de pé sozinha.','fase') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F12',1,'Escrever a versão comercial (2min)','2 minutos. Para vender: problema, solução, prova, próximo passo.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F12',2,'Escrever a versão institucional (5min)','5 minutos. Para investidor, parceiro ou evento: origem, crença, visão, prova.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F12',3,'Escrever a versão imprensa','Um parágrafo pronto para jornalista copiar e colar. Se ele reescrever, sai errado.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F12',4,'Rodar os testes de clareza, diferenciação, interesse e ação','Quem não conhece entendeu? serviria para o concorrente? deu vontade de saber mais? ficou claro o que fazer?',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F12',5,'Apresentar e registrar a aprovação do território verbal por escrito','Aceite formal do território verbal. Sem isso a fase visual começa sobre areia.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F13',13,'CRIANDO','Direção de arte','Transformar estratégia em direção visual concreta.',null,false,null,6,'M07 A14') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F13',0,'Conferir pré-requisitos: estratégia, posicionamento, verbal e Key Word aprovados','Se algum dos quatro não está aprovado, pare. Arte feita sobre estratégia aberta é retrabalho garantido.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F13',1,'Abrir o bloco de notas de ideias visuais guardado desde o começo','Desde a primeira call você anotou imagens, materiais, referências. É agora que isso serve.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F13',2,'Reler tudo e mapear palavras-chave recorrentes e o que é único','Que palavras se repetem em tudo que o cliente disse, e qual delas nenhum concorrente usa.','ex:VS1') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F13',3,'Criar 2 a 3 conceitos nomeados com justificativa estratégica','Dois ou três conceitos com nome próprio, cada um ligado a um atributo da estratégia. Conceito sem justificativa vira briga de gosto.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F13',4,'Montar os moodboards para validar as hipóteses','Moodboard não é decoração: é a hipótese do conceito em imagem, para o cliente reagir antes de você desenhar.','ex:VS1') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F13',5,'Apresentar e coletar reação com as 4 perguntas','O que você sente? o que isso comunica? o que combina com a marca? o que está fora?',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F13',6,'Registrar por escrito o conceito escolhido','Registre por escrito qual conceito foi escolhido e por quê. Sem isso, ele muda de ideia no meio da execução.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F14',14,'CRIANDO','Sistema de identidade','Criar ativos de marca, não peças soltas.','Sistema visual + Key Visual',true,'Cliente aprovou a identidade',15,'M07 A13/A15') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',0,'Desenvolver logo e variações','Principal, reduzida, símbolo isolado, versão monocromática e as regras de uso mínimo.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',1,'Definir paleta cromática (primárias, secundárias, funcionais)','Primárias definem a marca, secundárias dão respiro, funcionais avisam erro e sucesso.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',2,'Definir sistema tipográfico e hierarquia','Uma ou duas famílias, com pesos e tamanhos definidos para título, texto e legenda.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',3,'Definir linguagem gráfica (ilustração, foto, padrões, ícones)','O que preenche o espaço além do logo: fotografia, ilustração, padrão gráfico, ícones.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',4,'Definir arquitetura visual (grids, espaçamentos, composições)','Grid, margens e proporções. É o que faz peças diferentes parecerem da mesma marca.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',5,'Justificar cada elemento a partir de um atributo ou diretriz','Cada cor, forma e tipo precisa apontar para um atributo ou diretriz. Sem isso é gosto, não sistema.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',6,'Desenvolver o Key Visual','O documento que mostra a marca funcionando — estilo Style Scape, 3 slides. Deliberadamente sem refino: é fachada, não entrega final.','ex:VS3') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',7,'Testar o Key Visual SEM o logo','Tampe o logo. Se ninguém reconhece a marca, o sistema ainda não é proprietário.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',8,'Testar em 3 contextos e na menor escala de uso','Digital, impresso e ambiente — e na menor escala real de uso. É onde a maioria dos sistemas quebra.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',9,'Aplicar nos pontos de contato prioritários do diagnóstico','Nos pontos de contato que o diagnóstico apontou como críticos, não nos mais bonitos de portfólio.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F14',10,'Apresentar e registrar a aprovação por escrito','Aceite formal antes de partir para o guia. É a última âncora do projeto.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_phases (id,ord,macro,name,objective,deliverable,is_gate,gate_label,default_days,source) values ('F15',15,'DEFININDO','Guia de marca','Empacotar e transferir. É do cliente, não seu.','Guia de Marca',false,null,8,'M07 A16') on conflict (id) do update set ord=excluded.ord, macro=excluded.macro, name=excluded.name, objective=excluded.objective, deliverable=excluded.deliverable, is_gate=excluded.is_gate, gate_label=excluded.gate_label, default_days=excluded.default_days, source=excluded.source;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',0,'Escolher o formato adequado ao cliente, não ao portfólio','Site, PDF, Notion, pôster. Escolha pelo que o time do cliente vai realmente abrir no dia a dia.','ex:GM1') on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',1,'Montar na ordem: estratégia, posicionamento, verbal, visual','Estratégia primeiro, visual por último. Quem lê precisa entender o porquê antes do como.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',2,'Classificar cada diretriz: Fix (não muda), Flex (adapta) ou Free (livre)','Fix não muda nunca, Flex adapta ao contexto, Free é território livre. Sem isso o time congela ou faz besteira.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',3,'Marcar o que foi apenas direcionado para o time desenvolver','O que ficou como direção e não como peça pronta. Deixar isso claro evita cobrança de coisa que não foi contratada.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',4,'Escrever o capítulo de governança','Quem aprova o quê, com que frequência a marca é revisada, o que fazer quando aparece um caso novo.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',5,'Treinar o time do cliente','Uma sessão com o time. Guia entregue por e-mail não é usado — guia apresentado é.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',6,'Entregar arquivos e assets no Drive','Fontes, logos em vetor, paleta, templates. Organizado por pasta, na nomenclatura que eles usam.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
insert into nave_task_templates (phase_id,ord,title,detail,link) values ('F15',7,'Definir se encerra aqui ou emenda outro serviço','Encerra, vira retainer de marca ou emenda em campanha? Decida com o cliente antes de sumir.',null) on conflict (phase_id,ord) do update set title=excluded.title, detail=excluded.detail, link=excluded.link;
